// Build a single-file bundle of every design module — text-fx, effect-fx,
// glitter-fx, amp-bind. Outputs design/modules/all.css + design/modules/all.js
// so a composition needs ONE link + ONE script tag in <head> instead of 4-6.
//
// Run after editing any source module:
//   npm run build:bundle
//
// The bundle preserves the IIFE structure of each source — globals
// (textFx, effectFx, glitterFx, ampBind) stay exposed exactly as before.
//
// Source-of-truth is still the individual files. The bundle is regenerated.
// Don't hand-edit design/modules/all.{js,css}.

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const projectRoot = path.resolve(__dirname, "..");
const modulesDir = path.join(projectRoot, "design", "modules");

const cssSources = [
  "text-fx.css",
  "effect-fx.css",
  "glitter-fx.css",
  "combo-fx.css",
];
const jsSources = [
  // amp-bind sits in scripts/lib for legacy reasons — bundle it here too.
  path.join(projectRoot, "scripts", "lib", "amp-bind.js"),
  path.join(modulesDir, "text-fx.js"),
  path.join(modulesDir, "effect-fx.js"),
  path.join(modulesDir, "glitter-fx.js"),
  // combo-fx depends on the three above being registered already.
  path.join(modulesDir, "combo-fx.js"),
];

const bannerCss = `/* =========================================================================
   DESIGN MODULES — BUNDLE (auto-generated by scripts/build-bundle.mjs)
   =========================================================================
   Concatenation of: ${cssSources.join(", ")}
   Edit the source files, then \`npm run build:bundle\` to regenerate.
   ========================================================================= */
`;
const bannerJs = `// =========================================================================
// DESIGN MODULES — BUNDLE (auto-generated by scripts/build-bundle.mjs)
// =========================================================================
// Concatenation of: amp-bind.js, text-fx.js, effect-fx.js, glitter-fx.js, combo-fx.js
// Edit the source files, then \`npm run build:bundle\` to regenerate.
// Globals exposed: window.ampBind, window.textFx, window.effectFx, window.glitterFx, window.comboFx.
// =========================================================================
`;

function concat(parts, banner) {
  return banner + "\n\n" + parts.map((file) => {
    const abs = path.isAbsolute(file) ? file : path.join(modulesDir, file);
    const rel = path.relative(projectRoot, abs).replace(/\\/g, "/");
    const content = fs.readFileSync(abs, "utf8");
    return `/* ===== ${rel} ===== */\n${content}`;
  }).join("\n\n");
}

const cssOut = concat(cssSources, bannerCss);
const jsOut = concat(jsSources, bannerJs);

fs.writeFileSync(path.join(modulesDir, "all.css"), cssOut);
fs.writeFileSync(path.join(modulesDir, "all.js"), jsOut);

const cssBytes = Buffer.byteLength(cssOut);
const jsBytes = Buffer.byteLength(jsOut);
console.log(`✓ design/modules/all.css  ${(cssBytes / 1024).toFixed(1)} KB`);
console.log(`✓ design/modules/all.js   ${(jsBytes / 1024).toFixed(1)} KB`);
